"""Migrated validation rules for OPP_MASTER."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _field(image: dict | None, name: str) -> Any:
    """Return a field value, treating absent and None values as empty."""
    if image is None:
        return ""
    value = image.get(name, "")
    return "" if value is None else value


def _text(value: Any) -> str:
    """Convert a text/date/code value to its legacy string representation."""
    return "" if value is None else str(value)


def _nvl(value: Any, default: Any) -> Any:
    """Implement legacy NVL: only empty/missing/None values use the default."""
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    """Coerce legacy numeric values, where empty values compare as zero."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _date_ge(left: Any, right: Any) -> bool:
    """Legacy date >= comparison, including the 00000000 no-value sentinel."""
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image using migrated VRL rules."""
    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    amt = _field(record, "AMT")
    stat_cd = _text(_field(record, "STAT_CD"))
    lost_rsn = _text(_field(record, "LOST_RSN"))
    close_dt = _text(_field(record, "CLOSE_DT"))
    stage_pct = _number(_field(record, "STAGE_PCT"))

    if event in ("INSERT", "UPDATE"):
        # OPP-001
        if not (_number(_nvl(amt, 0)) >= Decimal(0)):
            fail("E3001", "Amount negative")

        # OPP-002
        if stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal(0):
            fail("E3002", "Won opportunity requires amount")

        # OPP-003
        if stat_cd == "L" and lost_rsn == "":
            fail("E3003", "Lost reason required")

        # OPP-004
        if stat_cd == "W" and close_dt == "00000000":
            fail("E3004", "Won opportunity requires close date")

    if event == "UPDATE":
        old_stat_cd = _text(_field(old, "STAT_CD"))
        # OPP-005
        if old_stat_cd == "W" and stat_cd != "W":
            fail("E3005", "Cannot reopen a won opportunity")

    if event in ("INSERT", "UPDATE"):
        # OPP-006
        stage_is_consistent = (
            (stat_cd == "P" and stage_pct == Decimal(10))
            or (stat_cd == "Q" and stage_pct == Decimal(25))
            or (stat_cd == "N" and stage_pct == Decimal(60))
            or (stat_cd == "W" and stage_pct == Decimal(100))
            or (stat_cd == "L" and stage_pct == Decimal(0))
        )
        if not stage_is_consistent:
            fail("E3006", "Stage percent inconsistent with status")

    if event == "INSERT":
        # OPP-007
        if not (close_dt == "00000000" or _date_ge(close_dt, today)):
            fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
